const mayFrame=f=>({...f.event,data:Buffer.from(f.event.data,'base64')});
module.exports.realMayFrames=realMayFrames;module.exports.mayFrame=mayFrame;
for(const mutation of ['invalid bool','unknown name','incorrect string length'])test('exact May buy rejects '+mutation,()=>{
 const f=realMayFrames.find(x=>x.expected.variant==='buy'),r=mayFrame(f);
 if(mutation==='invalid bool')r.data[368]=2;if(mutation==='unknown name')r.data[413]=120;if(mutation==='incorrect string length')r.data.writeUInt32LE(4,409);
 assert.equal(adapter.decodeEvent(r,f.parent),null);
});
for(const f of realMayFrames)test('real May row '+f.provenance.row+' '+f.expected.variant+' exact buyback tail is decoded',()=>{
 const e=adapter.decodeEvent(mayFrame(f),f.parent);
 assert.ok(e,'exact same-invocation known May event must decode, not EVENT_SOURCE_CONFLICT');
 assert.equal(e.buybackBasisPoints,f.expected.buybackBasisPoints);assert.equal(e.buybackFee,f.expected.buybackFee);assert.equal(e.cashback,f.expected.cashback);
 assert.equal(e.idlHash,'sha256:cd5c58a5dded23632aedb993b08cc0d2ba91bda2bb084560913464274d3bee50');
});
for(const variant of ['sell','buy','buy_exact_quote_in'])for(const mutation of ['truncated','overlong','wrong tag','wrong role','wrong path','wrong authority'])test('May '+variant+' rejects '+mutation+' event',()=>{
 const f=realMayFrames.find(x=>x.expected.variant===variant),r=mayFrame(f);
 if(mutation==='truncated')r.data=r.data.subarray(0,-1);if(mutation==='overlong')r.data=Buffer.concat([r.data,Buffer.from([0])]);
 if(mutation==='wrong tag')r.data[8]^=1;if(mutation==='wrong role')r.data[160]^=1;
 if(mutation==='wrong path')r.path=[99,...r.path.slice(1)];if(mutation==='wrong authority')r.accounts=['11111111111111111111111111111111'];
 assert.equal(adapter.decodeEvent(r,f.parent),null);
});
test('synthetic existing owned account with actual matching final CloseAccount derives post zero',()=>{
 const raw=h.parse(Buffer.from(fragments[0].raw)),ctx=adapter.context(raw),account=raw.transaction.message.accountKeys[1],owner=raw.transaction.message.accountKeys[0];
 // A separate setup: account already existed, so remove its create/init records.
 // The exact accepted close instruction and transfer paths remain the oracle.
 ctx.records=ctx.records.filter(r=>!(r.program==='11111111111111111111111111111111'&&r.accounts[1]===account&&r.data.length===52)&&!(r.program==='TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA'&&r.accounts[0]===account&&[1,16,18].includes(r.data[0])));
 const states=adapter.deriveLifecycle(ctx,[{signature:raw.transaction.signatures[0],account,preMint:'So11111111111111111111111111111111111111112',preOwner:owner,preAmount:'764275565',preDecimals:9,postMint:null,postOwner:null,postAmount:null,postDecimals:null}],[]);
 assert.equal(states[0].postAmount,'0','matching observed final close must establish zero post-state');assert.equal(states[0].preAmount,'764275565');
});
